/* Century Gothic look-alike (URW Gothic, GPL with PDF-embedding exception) for jsPDF documents.
   Every new jsPDF document gets the font registered and the built-in "helvetica" mapped to it. */
(function(){
var F={"normal":"","bold":"","italic":"","bolditalic":""};
function boot(){var ns=window.jspdf;if(!ns||!ns.jsPDF||ns.jsPDF.__cg)return;var Orig=ns.jsPDF;
 function CG(){var d=new(Function.prototype.bind.apply(Orig,[null].concat([].slice.call(arguments))))();
  try{["normal","bold","italic","bolditalic"].forEach(function(s){var fn="CenturyGothic-"+s+".ttf";d.addFileToVFS(fn,F[s]);d.addFont(fn,"CenturyGothic",s)});
   var sf=d.setFont.bind(d);d.setFont=function(n,s,w){if(!n||/^(helvetica|arial|times|courier|sans-serif)$/i.test(n))n="CenturyGothic";if(n=="CenturyGothic"&&s==null)s="normal";return sf(n,s,w)};d.setFont("CenturyGothic","normal")}catch(e){if(window.console)console.warn("Century Gothic font not loaded",e)}
  return d}
 CG.prototype=Orig.prototype;for(var k in Orig)try{CG[k]=Orig[k]}catch(e){}CG.API=Orig.API;CG.__cg=1;ns.jsPDF=CG}
boot();if(!(window.jspdf&&window.jspdf.jsPDF))window.addEventListener("load",boot);
})();
